const menuButton=document.querySelector('.menu-toggle'),navigation=document.querySelector('#nav');
function closeMenu(){navigation.classList.remove('open');menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','Open navigation')}
menuButton.addEventListener('click',()=>{const open=!navigation.classList.contains('open');navigation.classList.toggle('open',open);menuButton.setAttribute('aria-expanded',String(open));menuButton.setAttribute('aria-label',open?'Close navigation':'Open navigation')});
document.addEventListener('click',e=>{if(!e.target.closest('.header'))closeMenu()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&navigation.classList.contains('open')){closeMenu();menuButton.focus()}});
window.matchMedia('(min-width:1001px)').addEventListener('change',e=>{if(e.matches)closeMenu()});
const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)');
const slides=[...document.querySelectorAll('.hero-slide')];let slideIndex=0,timer=null;
const play=document.querySelector('#slide-play');
function setSlide(index){slideIndex=(index+slides.length)%slides.length;slides.forEach((s,i)=>{s.classList.toggle('active',i===slideIndex);s.setAttribute('aria-hidden',String(i!==slideIndex))});document.querySelector('#slide-number').textContent=`0${slideIndex+1} / 0${slides.length}`}
function stopSlides(){if(timer)clearInterval(timer);timer=null;if(play){play.setAttribute('aria-pressed','false');play.setAttribute('aria-label','Play slideshow');play.textContent='▷'}}
if(slides.length){setSlide(0);document.querySelectorAll('[data-slide]').forEach(b=>b.addEventListener('click',()=>{stopSlides();setSlide(slideIndex+(b.dataset.slide==='next'?1:-1))}));play?.addEventListener('click',()=>{if(timer){stopSlides();return}timer=setInterval(()=>setSlide(slideIndex+1),6500);play.setAttribute('aria-pressed','true');play.setAttribute('aria-label','Pause slideshow');play.textContent='Ⅱ'});document.addEventListener('visibilitychange',()=>{if(document.hidden)stopSlides()});reducedMotion.addEventListener('change',e=>{if(e.matches)stopSlides()});let hx=0,hy=0;const hero=document.querySelector('.hero');hero.addEventListener('touchstart',e=>{hx=e.changedTouches[0].clientX;hy=e.changedTouches[0].clientY},{passive:true});hero.addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-hx,dy=e.changedTouches[0].clientY-hy;if(Math.abs(dx)>60&&Math.abs(dx)>Math.abs(dy)){stopSlides();setSlide(slideIndex+(dx<0?1:-1))}},{passive:true})}
const galleryItems=[...document.querySelectorAll('.gallery-item')];
document.querySelectorAll('.filter').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.filter').forEach(f=>{const selected=f===b;f.classList.toggle('selected',selected);f.setAttribute('aria-pressed',String(selected))});galleryItems.forEach(item=>{item.hidden=b.dataset.filter!=='All'&&item.dataset.category!==b.dataset.filter;if(!item.hidden){item.classList.remove('pending');item.classList.add('visible')}});const count=galleryItems.filter(i=>!i.hidden).length;document.querySelector('.gallery-status').textContent=`${count} inspiration image${count===1?'':'s'}`}));
const lightbox=document.querySelector('#lightbox');let visibleItems=[],currentImage=0,opener;
function showImage(index){if(!visibleItems.length)return;currentImage=(index+visibleItems.length)%visibleItems.length;const item=visibleItems[currentImage],im=document.querySelector('#lightbox-image');im.src=item.dataset.image;im.alt=item.dataset.alt;document.querySelector('#lightbox-title').textContent=item.dataset.title;document.querySelector('#image-count').textContent=`${currentImage+1} / ${visibleItems.length}`}
if(lightbox){galleryItems.forEach(item=>item.addEventListener('click',()=>{opener=item;visibleItems=galleryItems.filter(i=>!i.hidden);showImage(visibleItems.indexOf(item));lightbox.showModal();document.body.style.overflow='hidden'}));document.querySelector('.lightbox-close').addEventListener('click',()=>lightbox.close());lightbox.addEventListener('close',()=>{document.body.style.overflow='';opener?.focus()});document.querySelector('.lightbox-prev').addEventListener('click',()=>showImage(currentImage-1));document.querySelector('.lightbox-next').addEventListener('click',()=>showImage(currentImage+1));lightbox.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();showImage(currentImage-1)}if(e.key==='ArrowRight'){e.preventDefault();showImage(currentImage+1)}});let sx=0,sy=0;lightbox.addEventListener('touchstart',e=>{sx=e.changedTouches[0].clientX;sy=e.changedTouches[0].clientY},{passive:true});lightbox.addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-sx,dy=e.changedTouches[0].clientY-sy;if(Math.abs(dx)>60&&Math.abs(dx)>Math.abs(dy))showImage(currentImage+(dx<0?1:-1))},{passive:true})}
const form=document.querySelector('#enquiry-form');
if(form){const now=new Date();now.setMinutes(now.getMinutes()-now.getTimezoneOffset());form.elements.date.min=now.toISOString().slice(0,10);for(const name of ['name','phone','location'])form.elements[name].addEventListener('input',()=>form.elements[name].setCustomValidity(''));form.addEventListener('submit',e=>{e.preventDefault();for(const name of ['name','location']){const field=form.elements[name];field.value=field.value.trim();field.setCustomValidity(field.value?'':'Please enter this detail.')}const raw=form.elements.phone.value.trim(),digits=raw.replace(/\D/g,'');form.elements.phone.setCustomValidity(/^[+0-9 ()-]+$/.test(raw)&&digits.length>=10&&digits.length<=15?'':'Please enter a phone number with 10 to 15 digits.');if(!form.reportValidity())return;const d=new FormData(form),lines=['Hello Purple Fox Event Planners! I would like to plan an event.','',`Name: ${d.get('name')}`,`Mobile: ${d.get('phone')}`,`Event: ${d.get('event')}`,`Preferred date: ${d.get('date')}`,`City / venue: ${d.get('location')}`];if(d.get('guests'))lines.push(`Expected guests: ${d.get('guests')}`);if(d.get('budget'))lines.push(`Approximate budget: ${d.get('budget')}`);if(String(d.get('details')).trim())lines.push(`Special requirements: ${String(d.get('details')).trim()}`);const url=document.querySelector('.floating-wa').href.split('?')[0]+'?text='+encodeURIComponent(lines.join('\n'));const fallback=document.createElement('a');fallback.href=url;fallback.target='_blank';fallback.rel='noopener noreferrer';fallback.className='text-link';fallback.textContent='Message ready. Open WhatsApp to review and send ↗';document.querySelector('#form-status').replaceChildren(fallback);window.open(url,'_blank','noopener,noreferrer')})}
if('IntersectionObserver' in window&&!reducedMotion.matches){const observer=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){entry.target.classList.remove('pending');entry.target.classList.add('visible');observer.unobserve(entry.target)}},{threshold:.07,rootMargin:'0px 0px 30px 0px'});document.querySelectorAll('.reveal').forEach(el=>{if(el.getBoundingClientRect().top>innerHeight){el.classList.add('pending');observer.observe(el)}});reducedMotion.addEventListener('change',e=>{if(e.matches){document.querySelectorAll('.pending').forEach(el=>el.classList.remove('pending'));observer.disconnect()}})}
